/**
 * ISO-5667-10 regulation-table seed builders (Plan 3 Task 20, 2026-09-18).
 *
 * SR-1: every seeded value and every `verbatim_quote` was read in this session
 * from the SPANISH transcript `Desktop\Ciruclar economy, sustanability and water
 * test\ISO 5667-10\ISO-5667-10.txt` (1883 lines; AENOR licence copy of the Spanish
 * translation of ISO 5667-10:2020, pdftotext). The spans live in
 * `regulation-tables-quotes-iso5667_10.ts` (generated by line range, never
 * retyped); the line range is in each span's name. A Spanish plain-text
 * transcript is a VC-grade source by ruling (no PDF read) — EVERY table here
 * ships `verification_status: 'imported_unverified'`; nothing is upgraded.
 * Verified by `scripts/regulation-tables/verify-regulation-tables.ts iso5667_10 "<transcript>"`.
 * Emitted as `20260917102000_regulation_tables_seed_iso5667_10.sql` (no earlier
 * ISO-5667-10 table seed exists — nothing superseded).
 *
 * Edition: the title page prints "Segunda edición" / "2020-11" (L7–L8); prod
 * `standards.version` is "2020 (ISO 5667-10:2020, second edition; ISO/TC 147/SC 6)"
 * (read-only 2026-09-18) → token `'2020'`.
 *
 * The standard prints NO numeric table: every "table" below is a printed
 * SENTENCE rule (threshold per context) or a printed formula switch, one row per
 * printed alternative, so the worksheet limits can be switched by context
 * instead of hard-coded (inventory §5 win 4). Key tokens (G-A3): S4_3_2.n_band
 * (gt25 / lt25) and S7_2_1.duration (h2 / h24) are the tokens of the equations /
 * the select CREATED by `field-configs/iso5667_10.ts`; S7_2_2_1_TUBE.bore_band
 * (ge9 / ge12) is chosen inside the ISO-5667-10-06-D4 equation;
 * S7_2_2_1_PUMP.pump = prod `pump_technology` tokens (vacuum / inline_piston —
 * peristaltic / external print no figure, iso5667_10-E-1); S3_4.definicion =
 * prod `sample_type_definition` token `qualified_grab`; S9_1.homogenizer cells =
 * prod `homogenizer_type` tokens.
 *
 * Unreadable / ambiguous cells (all recorded, nothing corrected):
 *   - iso5667_10-U-1: the Formula (2) block (L494–L496) prints "𝐵+" for its first
 *     two terms and "𝐴+" for the rest while the legend (L500) defines only A —
 *     encoded as A + 52·k/n (the legend's symbol); the row keeps the printed
 *     glyphs verbatim.
 */
import type { RegulationTable, RegulationRow } from './regulation-tables';
import { Q } from './regulation-tables-quotes-iso5667_10';

const STD = 'ISO-5667-10';
export const ISO5667_10_EDITION = '2020';
const ED = ISO5667_10_EDITION;
const STATUS = 'imported_unverified' as const; // VC source (Spanish txt) — every table

/** Build-time SR-1 guard: every seeded cell text must be printed inside the named span. */
function inSpan(quote: string, cell: string | null, where: string): void {
  if (cell !== null && !quote.includes(cell)) throw new Error(`${where}: cell "${cell}" is not inside its verbatim span`);
}

// ---------------------------------------------------------------------------
// S4_3_2 — §4.3.2 formula switch (L478–L500): Formula (1) (days, 365/n) for n above about 25,
// Formula (2) (weeks, 52/n) for n below about 25; A random in (−365/n, 0) resp. (−52/n, 0).
// Read by the ISO-5667-10-03 equations and the `probenahmetermine` row expr; the "unas 25"
// boundary (n = 25 exactly) is undefined by the text → encoded as `> 25` ⇒ gt25 (iso5667_10-J-1).
// Policy: L475–L476 "los días de muestreo pueden determinarse mediante una fórmula. Un ejemplo es:"
// + L502–L503 "Pueden utilizarse fórmulas similares para otros períodos" ⇒ anhaltswert (the brief
// said locked — iso5667_10-O-1).
// ---------------------------------------------------------------------------
export const S4_3_2_ROWS = [
  { band: 'gt25', label: 'n > ~25: Fórmula (1) — días', formula: '1', period_unit: 'días', period_length: 365, a_min_factor: '– 365/n', quote: Q.L478_489, printed: ['(1)', '365', '– 365/n y 0', 'días', 'superior a unas 25'] },
  { band: 'lt25', label: 'n < ~25: Fórmula (2) — semana', formula: '2', period_unit: 'semana', period_length: 52, a_min_factor: '– 52/n', quote: Q.L491_500, printed: ['(2)', '52', '– 52/n y 0', 'semana'] },
] as const;
export function s432AsTable(): RegulationTable {
  const rows: RegulationRow[] = S4_3_2_ROWS.map((r, i) => {
    for (const p of r.printed) inSpan(r.quote, p, `S4_3_2 ${r.band}`);
    return { row_key: r.band, keys: { n_band: r.band }, group_label: null, label_de: r.label, order_index: i,
      values: { formula: r.formula, period_unit: r.period_unit, period_length: r.period_length, a_min_factor: r.a_min_factor }, verbatim_quote: r.quote };
  });
  return { standard_code: STD, edition: ED, table_code: 'S4_3_2', title_de: 'Probenahmezeitpunkte über ein Jahr: Fórmula (1) Tage (365/n) vs. Fórmula (2) Wochen (52/n) nach Probenanzahl n (§4.3.2)', clause_reference: '§4.3.2, Fórmula (1), Fórmula (2)', page_ref: null,
    key_columns: ['n_band'],
    value_columns: [{ name: 'formula', type: 'string' }, { name: 'period_unit', type: 'string' }, { name: 'period_length', type: 'number' }, { name: 'a_min_factor', type: 'string' }],
    override_policy: 'anhaltswert',
    override_quote: `${Q.L475_476} — ${Q.L502_503}`,
    verification_status: STATUS, rows };
}

